#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────


# threecol live test (#32): the items only the author can run.
# Run:     bash reference/testwizard/wizard.sh
# Resume:  bash reference/testwizard/wizard.sh --resume <stage>
# Results: reference/testwizard/results.env (Claude turns them into checklist ticks).

HERE=$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)
REPO=$(git -C "$HERE" rev-parse --show-toplevel)
RUN="$HERE/.run"                       # logs, pids, backups for this run
ENV_FILE="$HERE/results.env"           # results, not secrets
TEST_WS=9
REPO_URL="https://github.com/PascalBrus/hyprland-layout"
PIN_0571="9fd58e0"
HL_COMMIT_0571="acc1aa0"
STATE_FILE="${XDG_STATE_HOME:-$HOME/.local/state}/threecol/dividers"
HYPR_CONF="$HOME/.config/hypr/hyprland.lua"
BUILD_SO="$REPO/build/threecol.so"
LOAD_LINE='hl.plugin.load(os.getenv("HOME") .. "/Projects/work/hyprland-layout/build/threecol.so")'
mkdir -p "$RUN"

# ── Hyprland helpers ─────────────────────────────────────────────────────────

# lua_run CODE runs Lua in the live session.
lua_run() { hyprctl dispatch "function() $1 end" >/dev/null; }

# lua_eval EXPR prints tostring(EXPR), evaluated in the live session.
lua_eval() {
  rm -f "$RUN/out"
  lua_run "local f = io.open('$RUN/out', 'w'); f:write(tostring($1)); f:close()"
  cat "$RUN/out" 2>/dev/null || true
}

# ws_pids prints the pids of the windows on the test workspace.
ws_pids() { hyprctl clients -j | jq -r --argjson ws "$TEST_WS" '.[] | select(.workspace.id == $ws) | .pid'; }

# win_size PID prints "width height" of that window.
win_size() { hyprctl clients -j | jq -r --argjson p "$1" '.[] | select(.pid == $p) | "\(.size[0]) \(.size[1])"' | head -n1; }

# so_path prints the threecol.so Hyprland has mapped (empty when none).
so_path() { grep threecol /proc/"$(pidof Hyprland)"/maps 2>/dev/null | awk '{print $6}' | sort -u | head -n1 || true; }

# open_test_windows opens ghostty windows on the test workspace, one at a time
# so they land in Fill order, until there are four. Pids go to $RUN/pids.
open_test_windows() {
  touch "$RUN/pids"
  local have; have=$(ws_pids | wc -l)
  while (( have < 4 )); do
    local before after new tries=0
    before=$(ws_pids | sort)
    hyprctl dispatch "hl.dsp.exec_cmd('ghostty --gtk-single-instance=false', { workspace = '$TEST_WS silent', no_initial_focus = true })" >/dev/null
    until (( $(ws_pids | wc -l) > have )) || (( tries++ > 75 )); do sleep 0.2; done
    after=$(ws_pids | sort)
    new=$(comm -13 <(printf '%s\n' "$before") <(printf '%s\n' "$after") | head -n1)
    [[ -n "$new" ]] || { warn "a test window didn't open; check ghostty, then re-run this stage"; exit 1; }
    echo "$new" >> "$RUN/pids"
    have=$((have + 1))
    sleep 0.5
  done
  note "test windows on workspace $TEST_WS: $(tr '\n' ' ' < "$RUN/pids")"
}

# nth_pid N prints the Nth test window (1 Master, 2 Left, 3 Stack top, 4 Stack bottom).
nth_pid() { sed -n "${1}p" "$RUN/pids"; }

# install_test_binds adds temporary runtime binds, gone at the next reload.
# Same flags as examples/binds.lua, plus a call counter, and they only act on
# the test workspace. SUPER+ALT+L is left alone: it locks the screen here.
install_test_binds() {
  lua_run "
    _G.TC_N = {}
    local function guarded(name, msg)
      return function()
        local ws = hl.get_active_workspace()
        if not (ws and ws.id == $TEST_WS) then return end
        TC_N[name] = (TC_N[name] or 0) + 1
        hl.dispatch(hl.dsp.layout(msg))
      end
    end
    hl.unbind('SUPER + ALT + H'); hl.bind('SUPER + ALT + H', guarded('H', 'resize narrower'), { repeating = true })
    hl.unbind('SUPER + ALT + K'); hl.bind('SUPER + ALT + K', guarded('K', 'resize taller'),   { repeating = true })
    hl.unbind('SUPER + ALT + J'); hl.bind('SUPER + ALT + J', guarded('J', 'resize shorter'),  { repeating = true })
    hl.unbind('SUPER + R');       hl.bind('SUPER + R',       guarded('R', 'reset'))
  "
  touch "$RUN/binds-installed"
}

remove_test_binds() {
  lua_run "hl.unbind('SUPER + ALT + H'); hl.unbind('SUPER + ALT + K'); hl.unbind('SUPER + ALT + J'); hl.unbind('SUPER + R'); _G.TC_N = nil"
  rm -f "$RUN/binds-installed"
}

back_ws() { cat "$RUN/orig_ws" 2>/dev/null || echo 1; }

count() { local n; n=$(lua_eval "(TC_N and TC_N['$1']) or 0"); echo "${n:-0}"; }

# run_logged NAME CMD runs CMD on a pty (so hyprpm's sudo and y/n prompts work)
# and keeps a copy of the output in $RUN/NAME.log. Returns CMD's exit code.
run_logged() {
  local name="$1"; shift
  printf '  %s$ %s%s\n' "$DIM" "$*" "$RESET"
  script -qefc "$*" "$RUN/$name.log"
}

run_wizard() {

TOTAL_STAGES=11

START=1
if [[ "${1:-}" == "--resume" ]]; then START="${2:?usage: --resume <stage number>}"; fi

# ── 1 ────────────────────────────────────────────────────────────────────────
s1() {
  stage "Preflight: version, plugin, backups"
  local v; v=$(hyprctl version | head -n1)
  say "$v"
  [[ "$v" == *"$HL_COMMIT_0571"* ]] || { warn "this isn't Hyprland 0.57.1 ($HL_COMMIT_0571); stop and tell Claude"; exit 1; }
  grep -q 'Plugin threecol' <<<"$(hyprctl plugin list)" || { warn "threecol isn't loaded; stop and tell Claude"; exit 1; }
  say "threecol loaded from: $(so_path)"

  if (( $(ws_pids | wc -l) > 0 )) && [[ ! -s "$RUN/pids" ]]; then
    warn "workspace $TEST_WS has windows that aren't from this wizard. Move or close them, then re-run."
    exit 1
  fi

  if [[ ! -f "$RUN/binds-installed" ]]; then
    local taken
    taken=$(hyprctl binds -j | jq -r '.[] | select((.modmask == 72 and (.key == "H" or .key == "J" or .key == "K")) or (.modmask == 64 and .key == "R")) | .key')
    [[ -z "$taken" ]] || { warn "your config already binds: $taken. The test binds would replace them; stop and tell Claude."; exit 1; }
  fi

  if [[ -f "$RUN/dividers.bak" ]]; then
    note "state file backup already taken earlier: $RUN/dividers.bak (kept)"
  else
    cp "$STATE_FILE" "$RUN/dividers.bak"
    printf '  %s✓ backed up%s %s → %s\n' "$GREEN" "$RESET" "$STATE_FILE" "$RUN/dividers.bak"
  fi
  hyprctl activeworkspace -j | jq -r .id > "$RUN/orig_ws"
  say ""
  say "Stages 2–5 run on workspace $TEST_WS with throw-away ghostty windows."
  say "Stages 6–11 install threecol through hyprpm, with one logout in between."
  pause "Press Enter to continue"
}

# ── 2 ────────────────────────────────────────────────────────────────────────
s2() {
  stage "Resize keys repeat when held"
  say "Opening 4 test windows on workspace $TEST_WS and adding temporary binds"
  say "(SUPER+ALT+H/K/J, repeating, like examples/binds.lua; they only act on $TEST_WS)."
  open_test_windows
  install_test_binds
  lua_run "TC_N = {}"
  local lw0 lh0; read -r lw0 _ <<<"$(win_size "$(nth_pid 2)")"; read -r _ lh0 <<<"$(win_size "$(nth_pid 3)")"
  local back; back=$(back_ws)
  say ""
  say "${BOLD}Remember these, then go:${RESET}"
  step "SUPER+$TEST_WS to go to the test workspace."
  step "Click the ${BOLD}narrow window on the left${RESET} (Left zone). Hold SUPER+ALT+H for ~2 s: it should keep shrinking."
  step "Click the ${BOLD}top-right window${RESET} (Stack top Row). Hold SUPER+ALT+K ~2 s (grows), then SUPER+ALT+J ~2 s (shrinks)."
  step "SUPER+$back to come back here."
  note "SUPER+ALT+L isn't tested: it locks your screen. It has the same flags as H."
  pause "Press Enter when you're back"

  local h k j lw1 lh1
  h=$(count H); k=$(count K); j=$(count J)
  read -r lw1 _ <<<"$(win_size "$(nth_pid 2)")"; read -r _ lh1 <<<"$(win_size "$(nth_pid 3)")"
  say "SUPER+ALT+H fired $h×  (Left width $lw0 → $lw1 px)"
  say "SUPER+ALT+K fired $k×, SUPER+ALT+J fired $j×  (Stack top Row height now $lh1 px, was $lh0)"
  local verdict="fail"
  (( h > 1 && k > 1 && j > 1 )) && verdict="pass"
  (( h == 0 || k == 0 || j == 0 )) && { warn "a key never fired on workspace $TEST_WS; re-run with --resume 2 to try again"; verdict="incomplete"; }
  say "Verdict: ${BOLD}$verdict${RESET} (each held key should fire more than once)"
  ask NOTE_RESIZE "Anything you noticed (Enter for nothing):" || true
  write_env RESIZE_KEYS_REPEAT "$verdict: held H fired ${h}x, K ${k}x, J ${j}x; Left ${lw0}->${lw1}px. ${NOTE_RESIZE:-}"
  pause
}

# ── 3 ────────────────────────────────────────────────────────────────────────
s3() {
  stage "SUPER+R doesn't repeat when held"
  open_test_windows
  [[ -f "$RUN/binds-installed" ]] || install_test_binds
  lua_run "TC_N = {}"
  local back; back=$(back_ws)
  say "A temporary SUPER+R (reset, not repeating, like examples/binds.lua) counts its calls."
  step "SUPER+$TEST_WS, click any test window."
  step "Hold SUPER+R for ~2 s. The layout snaps back to the default shape once."
  step "SUPER+$back to come back here."
  pause "Press Enter when you're back"
  local r verdict; r=$(count R)
  case "$r" in
    1) verdict="pass" ;;
    0) verdict="incomplete"; warn "SUPER+R never fired on workspace $TEST_WS; re-run with --resume 3" ;;
    *) verdict="fail" ;;
  esac
  say "SUPER+R fired $r× → ${BOLD}$verdict${RESET} (expected exactly 1)"
  ask NOTE_RESET "Anything you noticed (Enter for nothing):" || true
  write_env RESET_NO_REPEAT "$verdict: held SUPER+R fired ${r}x. ${NOTE_RESET:-}"
  pause
}

# ── 4 ────────────────────────────────────────────────────────────────────────
s4() {
  stage "Drop indicator and new-window jump (visual)"
  open_test_windows
  local back; back=$(back_ws)
  say "Your call on how these look. Expected:"
  note "Drop indicator: one rectangle where the window will land, in the active-border"
  note "colour (gradient as Hyprland draws it), ~20% fill, with the layout's gaps and"
  note "rounding. Above the tiles, below the dragged window."
  note "New window: opens straight at its final size, no visible jump or resize."
  say ""
  step "SUPER+$TEST_WS. SUPER+left-drag the bottom-right window slowly over Master, then over Left,"
  step "then onto the bottom quarter of the Stack (the \"add\" area). Watch the rectangle. Drop anywhere."
  step "Press SUPER+Return a few times and watch each new window appear. Close those with SUPER+W."
  step "SUPER+$back to come back here."
  pause "Press Enter when you're back"
  ask DROP_INDICATOR "Drop indicator: pass/fail + what you saw:"
  write_env DROP_INDICATOR "$DROP_INDICATOR"
  ask NO_VISIBLE_JUMP "New windows without a visible jump: pass/fail + note:"
  write_env NO_VISIBLE_JUMP "$NO_VISIBLE_JUMP"
  pause
}

# ── 5 ────────────────────────────────────────────────────────────────────────
s5() {
  stage "Clean up workspace $TEST_WS"
  local back; back=$(back_ws)
  if [[ -s "$RUN/pids" ]] && (( $(ws_pids | wc -l) > 0 )); then
    hyprctl dispatch "hl.dsp.focus({ workspace = $TEST_WS })" >/dev/null; sleep 0.3
    if [[ "$(hyprctl activewindow -j | jq -r '.workspace.id // empty')" == "$TEST_WS" ]]; then
      hyprctl dispatch "hl.dsp.layout('reset')" >/dev/null   # drops workspace $TEST_WS's saved entry
      note "reset workspace $TEST_WS's Dividers (removes its saved entry)"
    fi
    hyprctl dispatch "hl.dsp.focus({ workspace = $back })" >/dev/null
  fi
  local pid
  while read -r pid; do
    if [[ -n "$pid" && "$(cat /proc/"$pid"/comm 2>/dev/null)" == ghostty ]]; then
      kill "$pid" || true; note "closed test window pid $pid"
    fi
  done < "$RUN/pids"
  : > "$RUN/pids"
  remove_test_binds
  note "removed the temporary binds"
  sleep 0.5
  cp "$RUN/dividers.bak" "$STATE_FILE"
  if cmp -s "$RUN/dividers.bak" "$STATE_FILE"; then
    printf '  %s✓ state file restored%s from the backup\n' "$GREEN" "$RESET"
  else
    warn "state file differs from the backup: compare $STATE_FILE with $RUN/dividers.bak"
  fi
  local left; left=$(ws_pids | wc -l)
  (( left == 0 )) || warn "$left window(s) still on workspace $TEST_WS (ones you opened?); close them yourself"
  pause
}

# ── 6 ────────────────────────────────────────────────────────────────────────
s6() {
  stage "hyprpm update: Hyprland headers"
  say "hyprpm needs the Hyprland headers before it can build plugins."
  say "It asks for your sudo password (it creates /var/cache/hyprpm) and takes a few minutes."
  confirm "Run 'hyprpm update' now?" || { SKIPPED+=("hyprpm update (stages 6–11)"); warn "skipped; resume later with --resume 6"; exit 0; }
  local rc=0; run_logged hyprpm-update hyprpm update -v || rc=$?
  if (( rc )); then
    warn "hyprpm update failed (exit $rc). Log: $RUN/hyprpm-update.log. Stop here and tell Claude."
    write_env HYPRPM_HEADERS "fail: exit $rc, log $RUN/hyprpm-update.log"
    exit 1
  fi
  write_env HYPRPM_HEADERS "ok"
  pause
}

# ── 7 ────────────────────────────────────────────────────────────────────────
s7() {
  stage "hyprpm add + enable threecol"
  say "Now threecol gets loaded by hyprpm instead of from build/threecol.so."
  warn "First the build/ copy is unloaded, so two copies never load at once. Until hyprpm"
  warn "loads its copy (a minute or two of building) every workspace uses dwindle, and when"
  warn "threecol comes back, open windows are re-placed in Fill order (Holes and Row heights lost)."
  confirm "Unload build/threecol.so and install through hyprpm?" || { warn "stopped; resume with --resume 7"; exit 0; }

  if [[ "$(so_path)" == "$BUILD_SO" ]]; then
    hyprctl plugin unload "$BUILD_SO" && note "unloaded $BUILD_SO"
  fi
  local rc=0
  say "hyprpm asks whether you trust the author: answer y."
  if grep -q threecol <<<"$(hyprpm list 2>&1)"; then
    note "threecol is already added to hyprpm; skipping 'hyprpm add'"
  else
    run_logged hyprpm-add hyprpm add "$REPO_URL" -v || rc=$?
  fi
  (( rc == 0 )) && { run_logged hyprpm-enable hyprpm enable threecol -v || rc=$?; }
  (( rc == 0 )) && { run_logged hyprpm-reload hyprpm reload -n || rc=$?; }
  sleep 1

  local so; so=$(so_path)
  if (( rc )) || [[ -z "$so" ]]; then
    warn "hyprpm didn't get threecol loaded (exit $rc). Logs: $RUN/hyprpm-add.log, hyprpm-enable.log"
    if confirm "Load build/threecol.so again so your session has threecol back?"; then
      hyprctl plugin load "$BUILD_SO" && note "reloaded $BUILD_SO"
    fi
    write_env HYPRPM_ADD_ENABLE "fail: exit $rc, threecol not loaded via hyprpm; logs in $RUN"
    exit 1
  fi
  say "threecol now loaded from: $so"
  local gtest pin
  gtest=$(grep -ciE 'gtest|googletest' "$RUN/hyprpm-add.log" 2>/dev/null || true)
  pin=$(grep -c "$PIN_0571" "$RUN/hyprpm-add.log" 2>/dev/null || true)
  gtest=${gtest:-0}; pin=${pin:-0}
  say "GoogleTest mentions in the build log: $gtest (expected 0)"
  say "Pinned commit $PIN_0571 in the log: $( (( pin > 0 )) && echo yes || echo "not printed (Claude will check)")"
  local verdict="pass"; [[ "$so" == "$BUILD_SO" || "$gtest" != 0 ]] && verdict="fail"
  write_env HYPRPM_ADD_ENABLE "$verdict: loaded from $so; gtest mentions $gtest; pin in log: $pin"
  pause
}

# ── 8 ────────────────────────────────────────────────────────────────────────
s8() {
  stage "hyprpm update builds the pinned commit"
  say "With threecol installed, 'hyprpm update' should (re)build threecol at $PIN_0571,"
  say "the commit pinned for Hyprland 0.57.1 in hyprpm.toml."
  local cmd="hyprpm update -v"
  confirm "Force a full rebuild (-f: headers + plugin, a few minutes, sudo)? No = plain update" && cmd="hyprpm update -f -v"
  local rc=0; run_logged hyprpm-update2 $cmd || rc=$?
  run_logged hyprpm-reload2 hyprpm reload -n || true
  local pin; pin=$(grep -c "$PIN_0571" "$RUN/hyprpm-update2.log" || true)
  say "exit $rc; $PIN_0571 in the log: $pin; threecol loaded from: $(so_path)"
  local verdict="pass"; (( rc )) && verdict="fail"; [[ -z "$(so_path)" ]] && verdict="fail"
  write_env HYPRPM_UPDATE_PIN "$verdict: '$cmd' exit $rc; pin in log: $pin; log $RUN/hyprpm-update2.log"
  pause
}

# ── 9 ────────────────────────────────────────────────────────────────────────
s9() {
  stage "Load threecol through hyprpm at start-up, then log out"
  say "Your hyprland.lua loads build/threecol.so directly. For the start-up test it should"
  say "load threecol the way the README says: 'hyprpm reload' on hyprland.start."
  step "Backup:  $HYPR_CONF → $RUN/hyprland.lua.bak"
  step "Comment out:  $LOAD_LINE"
  step "Add below it:  hl.on(\"hyprland.start\", function() hl.exec_cmd(\"hyprpm reload\") end)"
  warn "Hyprland reloads the config as soon as the file changes; threecol stays loaded, but"
  warn "open windows get re-placed in Fill order (bug #37)."
  if grep -qF -- "-- threecol live test (#32)" "$HYPR_CONF"; then
    note "already switched earlier"
  else
    if ! grep -qxF -- "$LOAD_LINE" "$HYPR_CONF"; then
      warn "couldn't find that exact line in $HYPR_CONF. Make the change by hand, then"
      warn "add a line '-- threecol live test (#32)' and re-run with --resume 9."
      exit 1
    fi
    confirm "Edit $HYPR_CONF now?" || { warn "stopped; resume with --resume 9"; exit 0; }
    [[ -f "$RUN/hyprland.lua.bak" ]] || cp "$HYPR_CONF" "$RUN/hyprland.lua.bak"
    LOAD_LINE="$LOAD_LINE" python3 - "$HYPR_CONF" <<'PY'
import os, sys
path, line = sys.argv[1], os.environ["LOAD_LINE"]
text = open(path).read()
new = ("-- threecol live test (#32): loaded by hyprpm; backup in reference/testwizard/.run\n"
       "-- " + line + "\n"
       'hl.on("hyprland.start", function()\n'
       '    hl.exec_cmd("hyprpm reload")\n'
       "end)")
open(path, "w").write(text.replace(line, new, 1))
PY
    printf '  %s✓ edited%s %s\n' "$GREEN" "$RESET" "$HYPR_CONF"
    diff "$RUN/hyprland.lua.bak" "$HYPR_CONF" || true
  fi
  say ""
  say "${BOLD}Now log out and back in:${RESET}"
  step "SUPER+SHIFT+Q (uwsm stop), log in again."
  step "Right after login, watch the screen: workspaces may tile like dwindle for about a"
  step "second, then switch to threecol. Note any threecol/hyprpm notification."
  step "Open a terminal and run:  bash $HERE/wizard.sh --resume 10"
  write_env NEXT_STAGE "10"
  exit 0
}

# ── 10 ───────────────────────────────────────────────────────────────────────
s10() {
  stage "Start-up with hyprpm"
  local so layouts
  so=$(so_path)
  layouts=$(hyprctl workspaces -j | jq -r '[.[].tiledLayout] | unique | join(",")')
  say "threecol loaded from: ${so:-NOT LOADED}"
  say "layouts in use: $layouts"
  hyprpm list 2>&1 | sed 's/^/  /' | head -n 8 || true
  local auto="pass"
  [[ -z "$so" || "$so" == "$BUILD_SO" || "$layouts" != "threecol" ]] && auto="fail"
  say "Automatic check: ${BOLD}$auto${RESET} (loaded by hyprpm, every workspace on threecol)"
  note "The 'windows already open are placed in Fill order' half was simulated in the nested pass."
  ask STARTUP_SEEN "What did you see at login (brief dwindle? notifications?) + pass/fail:"
  write_env HYPRPM_STARTUP "$auto (auto): loaded from ${so:-none}, layouts $layouts. Author: $STARTUP_SEEN"
  pause
}

# ── 11 ───────────────────────────────────────────────────────────────────────
s11() {
  stage "Keep hyprpm, or go back to build/threecol.so"
  say "With hyprpm, your session runs the pinned release build, not your local build/."
  say "Going back restores your hyprland.lua backup and disables the hyprpm copy."
  if confirm "Keep loading threecol through hyprpm?"; then
    write_env HYPRPM_KEPT "yes"
  else
    [[ -f "$RUN/hyprland.lua.bak" ]] || { warn "no backup at $RUN/hyprland.lua.bak; revert $HYPR_CONF by hand"; exit 1; }
    run_logged hyprpm-disable hyprpm disable threecol || true
    cp "$RUN/hyprland.lua.bak" "$HYPR_CONF"
    note "restored $HYPR_CONF (Hyprland reloads it and loads build/threecol.so)"
    sleep 3
    if [[ "$(so_path)" == "$BUILD_SO" ]]; then
      printf '  %s✓ threecol loaded%s from %s\n' "$GREEN" "$RESET" "$BUILD_SO"
    else
      warn "build/threecol.so isn't loaded yet; run 'hyprctl reload' (it re-places windows, #37)"
    fi
    write_env HYPRPM_KEPT "no (config restored)"
  fi
  pause
}

banner "threecol live test (#32): your items"
for (( i = 1; i <= TOTAL_STAGES; i++ )); do
  if (( i < START )); then _STAGE_INDEX=$i; continue; fi
  "s$i"
done

finish
say "Results are in $ENV_FILE. Tell Claude you're done; it will tick the checklist."
note "GIF for the README (Showcase) isn't part of this wizard."
printf '\n'
}

run_wizard "$@"; exit
